insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":6739,"materia":"enf","nivel":2,"enunciado":"Prescritos 500 mL de SF 0,9% em 4 horas, com equipo de macrogotas. O gotejamento é de aproximadamente:","opcoes":["42 gotas/min","125 gotas/min","21 gotas/min","83 gotas/min"],"explicacao":"Gotas/min = volume ÷ (horas × 3) = 500 ÷ 12 ≈ 41,7."},{"id":6740,"materia":"enf","nivel":2,"enunciado":"Prescritos 1.000 mL de soro em 8 horas, com equipo de microgotas. O gotejamento é de:","opcoes":["125 microgotas/min","42 microgotas/min","250 microgotas/min","62 microgotas/min"],"explicacao":"Microgotas/min = volume ÷ horas = 1.000 ÷ 8."},{"id":6741,"materia":"enf","nivel":3,"enunciado":"Um frasco de 500 mg foi diluído em 10 mL. Para administrar 150 mg, aspira-se:","opcoes":["3 mL","1,5 mL","5 mL","0,3 mL"],"explicacao":"500 mg — 10 mL; 150 mg — x. x = 3 mL."},{"id":6742,"materia":"enf","nivel":4,"enunciado":"Frasco de penicilina cristalina de 5.000.000 UI diluído em 8 mL de água destilada (o pó ocupa 2 mL). Para 2.000.000 UI, aspira-se:","opcoes":["4 mL","3,2 mL","2 mL","5 mL"],"explicacao":"O volume final é 10 mL: 5.000.000 UI — 10 mL; 2.000.000 UI — 4 mL."},{"id":6743,"materia":"enf","nivel":2,"enunciado":"Com insulina de 100 UI/mL, 10 UI correspondem a:","opcoes":["0,1 mL","1 mL","0,01 mL","10 mL"],"explicacao":"100 UI — 1 mL; 10 UI — 0,1 mL."},{"id":6744,"materia":"enf","nivel":2,"enunciado":"Heparina de 5.000 UI/mL: para 2.500 UI por via subcutânea, aspira-se:","opcoes":["0,5 mL","0,25 mL","2,5 mL","5 mL"],"explicacao":"Metade da concentração por mL."},{"id":6745,"materia":"enf","nivel":2,"enunciado":"Quantos gramas de glicose há em 500 mL de soro glicosado a 5%?","opcoes":["25 g","5 g","50 g","2,5 g"],"explicacao":"5% = 5 g em 100 mL; em 500 mL, 25 g."},{"id":6746,"materia":"enf","nivel":2,"enunciado":"Na bomba de infusão, 250 mL devem correr em 2 horas. A vazão programada é de:","opcoes":["125 mL/h","250 mL/h","50 mL/h","83 mL/h"],"explicacao":"250 ÷ 2 = 125."},{"id":6747,"materia":"enf","nivel":2,"enunciado":"Para paciente com tuberculose pulmonar bacilífera, a precaução indicada é:","opcoes":["Aerossóis, com máscara N95/PFF2","Gotículas, com máscara cirúrgica","Apenas contato, com luvas","Precaução padrão apenas"],"explicacao":"Quarto privativo, de preferência com pressão negativa."},{"id":6748,"materia":"enf","nivel":3,"enunciado":"Na meningite meningocócica, usa-se precaução para gotículas até:","opcoes":["24 horas de antibiótico eficaz","7 dias completos de internação","A alta hospitalar do paciente","O resultado do líquor"],"explicacao":"Depois disso, mantém-se a precaução padrão."},{"id":6749,"materia":"enf","nivel":3,"enunciado":"Para o paciente com varicela, as precauções indicadas são:","opcoes":["Aerossóis e contato","Só gotículas, com máscara cirúrgica","Só contato, com luvas e avental","Só padrão"],"explicacao":"O vírus se espalha pelo ar e pelo contato com as lesões."},{"id":6750,"materia":"enf","nivel":3,"enunciado":"No cuidado ao paciente com Clostridioides difficile, a higiene das mãos deve ser feita com:","opcoes":["Água e sabão","Só álcool em gel","Só luvas, sem lavar","Clorexidina alcoólica a 0,5%"],"explicacao":"O álcool não elimina os esporos."},{"id":6751,"materia":"enf","nivel":1,"enunciado":"Qual destes NÃO é um dos 5 momentos da higiene das mãos da OMS?","opcoes":["Ao chegar ao estacionamento do hospital","Antes de tocar o paciente","Após risco de exposição a fluidos","Após tocar superfícies próximas ao paciente"],"explicacao":"Os outros são: antes de procedimento limpo/asséptico e após tocar o paciente."},{"id":6752,"materia":"enf","nivel":3,"enunciado":"Lesão por pressão com perda parcial da espessura da pele e derme exposta, com leito rosado, é de estágio:","opcoes":["2","1","3","4"],"explicacao":"No estágio 1, a pele está íntegra, com eritema que não embranquece."},{"id":6753,"materia":"enf","nivel":3,"enunciado":"Lesão por pressão com perda total da pele e gordura visível, sem exposição de osso ou tendão, é de estágio:","opcoes":["3","2","4","1"],"explicacao":"No estágio 4, há exposição de fáscia, músculo, tendão, ligamento, cartilagem ou osso."},{"id":6754,"materia":"enf","nivel":4,"enunciado":"Lesão com perda total da pele cuja base está coberta por esfacelo ou escara, impedindo ver a profundidade, é classificada como:","opcoes":["Não classificável","Estágio 2","Tissular profunda","Estágio 1"],"explicacao":"Só após remover o tecido se define o estágio."},{"id":6755,"materia":"enf","nivel":4,"enunciado":"Área de pele íntegra, vermelho-escura ou púrpura, que não embranquece, sobre proeminência óssea, indica lesão por pressão:","opcoes":["Tissular profunda","Estágio 1","Estágio 2","Relacionada a dispositivo médico"],"explicacao":"Indica dano dos tecidos moles por pressão ou cisalhamento."},{"id":6756,"materia":"enf","nivel":2,"enunciado":"A escala de Braden avalia o risco de:","opcoes":["Lesão por pressão","Queda","Delirium","Desnutrição grave"],"explicacao":"Considera percepção sensorial, umidade, atividade, mobilidade, nutrição, fricção e cisalhamento."},{"id":6757,"materia":"enf","nivel":4,"enunciado":"Na escala de Braden para adultos, o escore que indica risco muito alto é:","opcoes":["9 ou menos","Entre 15 e 18","Entre 19 e 23","Exatamente 12"],"explicacao":"10 a 12: alto; 13 e 14: moderado; 15 a 18: baixo."},{"id":6758,"materia":"enf","nivel":4,"enunciado":"Paciente abre os olhos à pressão, emite sons incompreensíveis e faz flexão anormal (decorticação). A Escala de Coma de Glasgow (sem a reatividade pupilar) é:","opcoes":["7","6","8","5"],"explicacao":"Ocular 2 + verbal 2 + motor 3."},{"id":6759,"materia":"enf","nivel":3,"enunciado":"Um escore de Glasgow de 8 ou menos indica, em regra:","opcoes":["Necessidade de proteger a via aérea","Paciente lúcido e bem orientado","Possibilidade de alta no mesmo dia","Morte encefálica"],"explicacao":"Costuma indicar intubação."},{"id":6760,"materia":"enf","nivel":2,"enunciado":"Na RCP do adulto, as compressões torácicas devem ter profundidade de:","opcoes":["5 a 6 cm","2 a 3 cm","8 a 10 cm","1 a 2 cm"],"explicacao":"Com frequência de 100 a 120 por minuto e retorno total do tórax."},{"id":6761,"materia":"enf","nivel":3,"enunciado":"Na parada cardiorrespiratória, os ritmos chocáveis são:","opcoes":["FV e taquicardia ventricular sem pulso","Assistolia e atividade elétrica sem pulso","Bradicardia sinusal e assistolia","Fibrilação atrial e flutter"],"explicacao":"Assistolia e AESP não são chocáveis."},{"id":6762,"materia":"enf","nivel":4,"enunciado":"Na PCR em assistolia, a adrenalina é feita na dose de:","opcoes":["1 mg a cada 3 a 5 minutos","5 mg em dose única","0,1 mg a cada 10 minutos","1 mg a cada 30 segundos"],"explicacao":"Deve ser dada o quanto antes nos ritmos não chocáveis."},{"id":6763,"materia":"enf","nivel":2,"enunciado":"Pela Lei 7.498/1986, são privativas do enfermeiro:","opcoes":["Consulta e prescrição de enfermagem","Administração de qualquer medicamento","Verificação de sinais vitais","Higiene do paciente"],"explicacao":"Art. 11, I, da Lei do Exercício Profissional."},{"id":6764,"materia":"enf","nivel":3,"enunciado":"Pela Lei 7.498/1986, os cuidados diretos de enfermagem a pacientes graves com risco de vida são:","opcoes":["Privativos do enfermeiro","Do técnico, sem supervisão","Do auxiliar de enfermagem","De qualquer profissional de saúde"],"explicacao":"Art. 11, I, m."},{"id":6765,"materia":"enf","nivel":4,"enunciado":"Pela Resolução Cofen 736/2024, as cinco etapas do Processo de Enfermagem são:","opcoes":["Avaliação, diagnóstico, planejamento, implementação e evolução","Histórico, diagnóstico, prescrição, execução e alta","Coleta, exame físico, triagem, tratamento e alta","Anamnese, exame físico, prescrição e curativo"],"explicacao":"A resolução substituiu a 358/2009."},{"id":6766,"materia":"enf","nivel":4,"enunciado":"Na Resolução Cofen 736/2024, a etapa que corresponde ao antigo histórico de enfermagem chama-se:","opcoes":["Avaliação de Enfermagem","Coleta Preliminar","Anamnese Clínica","Triagem de Enfermagem"],"explicacao":"É a primeira das cinco etapas."},{"id":6767,"materia":"enf","nivel":2,"enunciado":"O diagnóstico de enfermagem é atividade:","opcoes":["Privativa do enfermeiro","Do técnico de enfermagem","Do auxiliar de enfermagem","Do médico"],"explicacao":"Lei 7.498/1986 e resoluções do Cofen."},{"id":6768,"materia":"enf","nivel":1,"enunciado":"Diante de uma prescrição ilegível ou duvidosa, o profissional de enfermagem deve:","opcoes":["Esclarecer com o prescritor antes","Executar como achar melhor","Perguntar ao paciente o que é","Executar e anotar depois"],"explicacao":"Código de Ética (Resolução Cofen 564/2017)."},{"id":6769,"materia":"enf","nivel":2,"enunciado":"Em crianças menores de 2 anos, o local preferido para injeção intramuscular é o músculo:","opcoes":["Vasto lateral da coxa","Deltoide do braço","Glúteo máximo","Bíceps braquial"],"explicacao":"É bem desenvolvido nessa idade."},{"id":6770,"materia":"enf","nivel":3,"enunciado":"A principal vantagem da região ventroglútea (Hochstetter) para injeção IM é:","opcoes":["Estar livre de grandes vasos e nervos","Ser a de absorção mais lenta do corpo","Aceitar volumes de até 20 mL","Dispensar antissepsia"],"explicacao":"Por isso é considerada a mais segura em adultos."},{"id":6771,"materia":"enf","nivel":3,"enunciado":"A técnica em Z (zigue-zague) na injeção intramuscular serve para:","opcoes":["Evitar o refluxo do medicamento","Acelerar a absorção pela veia","Dispensar a aspiração do êmbolo","Reduzir o volume da dose"],"explicacao":"Usada com ferro injetável, que mancha a pele."},{"id":6772,"materia":"enf","nivel":1,"enunciado":"Na rede de frio, as vacinas devem ser conservadas entre:","opcoes":["+2 °C e +8 °C","−20 °C e −10 °C","+10 °C e +15 °C","0 °C e +2 °C"],"explicacao":"Temperatura de referência para a maioria das vacinas."},{"id":6773,"materia":"enf","nivel":2,"enunciado":"A vacina BCG é aplicada por via:","opcoes":["Intradérmica, no braço direito","Intramuscular, no vasto lateral","Oral, em duas gotas","Subcutânea, na coxa"],"explicacao":"Na inserção inferior do deltoide direito."},{"id":6774,"materia":"enf","nivel":1,"enunciado":"Ao nascer, o calendário do PNI prevê as vacinas:","opcoes":["BCG e hepatite B","Tríplice viral e febre amarela","Pneumocócica e rotavírus","HPV e dTpa"],"explicacao":"De preferência nas primeiras horas de vida."},{"id":6775,"materia":"enf","nivel":4,"enunciado":"Desde 2024, os reforços contra a poliomielite no calendário infantil do PNI são feitos com:","opcoes":["Vacina inativada (VIP), injetável","Vacina oral (VOP), a gotinha","Vacina BCG","Nenhuma vacina; não há reforço"],"explicacao":"A VOP foi substituída pela VIP no esquema."},{"id":6776,"materia":"enf","nivel":2,"enunciado":"Para medir a sonda nasogástrica, usa-se a distância:","opcoes":["Do nariz ao lóbulo da orelha e daí ao apêndice xifoide","Da boca até a cicatriz umbilical","Do queixo ao ombro do mesmo lado","Da testa ao esterno"],"explicacao":"Marca-se a sonda nesse ponto."},{"id":6777,"materia":"enf","nivel":3,"enunciado":"O método mais seguro para confirmar a posição da sonda enteral antes de iniciar a dieta é:","opcoes":["Radiografia","Ausculta do ar injetado","Pedir para o paciente falar","Observar se ele tosse"],"explicacao":"A ausculta isolada não é confiável."},{"id":6778,"materia":"enf","nivel":2,"enunciado":"Para a lavagem intestinal, o paciente é colocado em posição de:","opcoes":["Sims (decúbito lateral esquerdo)","Trendelenburg, com a cabeça baixa","Prona, de barriga para baixo","Litotomia"],"explicacao":"Facilita a entrada da solução pelo trajeto do cólon."},{"id":6779,"materia":"enf","nivel":3,"enunciado":"Paciente consciente com glicemia capilar de 55 mg/dL. A conduta inicial recomendada é:","opcoes":["Dar 15 g de carboidrato rápido e reavaliar em 15 min","Aplicar insulina regular subcutânea","Aguardar a próxima refeição do paciente","Oferecer só água"],"explicacao":"É a \"regra dos 15\"."},{"id":6780,"materia":"enf","nivel":3,"enunciado":"Durante uma transfusão, o paciente tem febre, calafrios e dor lombar. A primeira conduta é:","opcoes":["Interromper a transfusão e manter acesso com SF 0,9%","Acelerar a infusão para terminar logo","Dar antitérmico e continuar a transfusão","Trocar a bolsa por outra"],"explicacao":"Pode ser reação hemolítica aguda."},{"id":6781,"materia":"enf","nivel":4,"enunciado":"Uma bolsa de concentrado de hemácias deve ser infundida em, no máximo:","opcoes":["4 horas","8 horas","12 horas","24 horas"],"explicacao":"Para reduzir o risco de contaminação bacteriana."},{"id":6782,"materia":"sus","nivel":0,"enunciado":"A Lei Orgânica da Saúde, que regula o SUS, é a Lei:","opcoes":["8.080/1990","8.069/1990","8.112/1990","11.340/2006"],"explicacao":"A Lei 8.142/1990 a complementa."},{"id":6783,"materia":"sus","nivel":1,"enunciado":"A Lei 8.142/1990 trata da:","opcoes":["Participação da comunidade e repasses de recursos","Criação do SAMU e das UPAs","Exercício profissional da enfermagem","Política de saúde mental"],"explicacao":"Criou as conferências e os conselhos de saúde."},{"id":6784,"materia":"sus","nivel":1,"enunciado":"São princípios doutrinários do SUS:","opcoes":["Universalidade, integralidade e equidade","Lucro, eficiência e mérito","Hierarquia, disciplina e ordem","Centralização, sigilo e seletividade"],"explicacao":"Os organizativos incluem descentralização e regionalização."},{"id":6785,"materia":"sus","nivel":2,"enunciado":"São princípios organizativos do SUS:","opcoes":["Descentralização, regionalização e hierarquização","Universalidade, integralidade e equidade","Equidade, gratuidade e lucro","Privatização e terceirização"],"explicacao":"Também a participação popular."},{"id":6786,"materia":"sus","nivel":2,"enunciado":"A Conferência de Saúde se reúne a cada:","opcoes":["4 anos","2 anos","1 ano","10 anos"],"explicacao":"Art. 1º, § 1º, da Lei 8.142/1990."},{"id":6787,"materia":"sus","nivel":3,"enunciado":"Nos conselhos de saúde, a representação dos usuários é:","opcoes":["Paritária em relação aos demais segmentos","Minoritária, com 10% das vagas","Inexistente, por falta de previsão legal","Indicada pelo prefeito"],"explicacao":"Art. 1º, § 4º, da Lei 8.142/1990: 50% das vagas."},{"id":6788,"materia":"sus","nivel":4,"enunciado":"Pelo Decreto 7.508/2011, são portas de entrada das Redes de Atenção à Saúde, entre outras:","opcoes":["Atenção primária, urgência e emergência e atenção psicossocial","Somente os hospitais universitários federais","Somente as farmácias do programa popular","Laboratórios privados"],"explicacao":"Art. 9º do Decreto 7.508/2011."},{"id":6789,"materia":"sus","nivel":4,"enunciado":"Pelo Decreto 7.508/2011, o acordo entre entes que organiza a rede de saúde numa região é o:","opcoes":["Contrato Organizativo da Ação Pública da Saúde (COAP)","Plano Plurianual de Investimentos do Município","Termo de Ajuste de Conduta com o MP","Convênio de Cooperação Técnica"],"explicacao":"Define responsabilidades, metas e recursos."},{"id":6790,"materia":"sus","nivel":2,"enunciado":"Pela PNAB de 2017, a equipe mínima de Saúde da Família tem:","opcoes":["Médico, enfermeiro, técnico ou auxiliar de enfermagem e ACS","Médico, dentista e técnico em saúde bucal apenas","Enfermeiro e agentes comunitários, sem médico","Médico, farmacêutico e psicólogo"],"explicacao":"Pode incluir profissionais de saúde bucal."},{"id":6791,"materia":"sus","nivel":4,"enunciado":"Pela PNAB de 2017, recomenda-se que cada equipe de Saúde da Família atenda uma população de:","opcoes":["2.000 a 3.500 pessoas","500 a 1.000 pessoas","8.000 a 10.000 pessoas","Até 750 pessoas"],"explicacao":"Conforme o grau de vulnerabilidade do território."},{"id":6792,"materia":"sus","nivel":4,"enunciado":"São atributos derivados da Atenção Primária, segundo Starfield:","opcoes":["Orientação familiar, comunitária e competência cultural","Primeiro contato, longitudinalidade e acesso","Coordenação, integralidade e resolutividade","Acesso, vínculo e porta de entrada"],"explicacao":"Os essenciais são primeiro contato, longitudinalidade, integralidade e coordenação."},{"id":6793,"materia":"sus","nivel":2,"enunciado":"A notificação compulsória imediata deve ser feita em até:","opcoes":["24 horas","7 dias","30 dias","48 horas"],"explicacao":"A semanal, em até 7 dias."},{"id":6794,"materia":"sus","nivel":1,"enunciado":"Qual destas doenças é de notificação compulsória?","opcoes":["Sarampo","Hipertensão","Asma","Miopia"],"explicacao":"Lista nacional de notificação compulsória."},{"id":6795,"materia":"sus","nivel":3,"enunciado":"Pela LC 141/2012, os municípios devem aplicar em saúde, no mínimo:","opcoes":["15% da receita de impostos e transferências","12% da receita de impostos e transferências","25% da receita corrente líquida","10% da receita"],"explicacao":"Os estados, 12%."},{"id":6796,"materia":"sus","nivel":4,"enunciado":"Pela LC 141/2012, os estados devem aplicar em saúde, no mínimo:","opcoes":["12% da receita de impostos e transferências","15% da receita de impostos e transferências","10% da receita corrente líquida","20% da receita"],"explicacao":"Os municípios, 15%."},{"id":6797,"materia":"sus","nivel":1,"enunciado":"O acolhimento com classificação de risco organiza o atendimento:","opcoes":["Pela gravidade do caso","Por ordem de chegada","Por idade, apenas","Por sorteio"],"explicacao":"Proposto pela Política Nacional de Humanização."},{"id":6798,"materia":"sus","nivel":3,"enunciado":"No Protocolo de Manchester, a cor amarela (urgente) prevê atendimento em até:","opcoes":["60 minutos","10 minutos","240 minutos","Imediato"],"explicacao":"Vermelho: imediato; laranja: 10 min; verde: 120 min; azul: 240 min."},{"id":6799,"materia":"sus","nivel":2,"enunciado":"A taxa de mortalidade infantil considera os óbitos de crianças com menos de:","opcoes":["1 ano, por mil nascidos vivos","5 anos, por mil habitantes","10 anos, por cem mil habitantes","28 dias, por cem nascidos"],"explicacao":"Os óbitos até 27 dias são a mortalidade neonatal."},{"id":6800,"materia":"sus","nivel":2,"enunciado":"A incidência de uma doença mede:","opcoes":["Os casos novos num período","Todos os casos existentes","Só os óbitos","Os casos curados"],"explicacao":"A prevalência mede os casos existentes."},{"id":6801,"materia":"sus","nivel":3,"enunciado":"A prevenção quaternária busca:","opcoes":["Evitar intervenções médicas desnecessárias","Vacinar a população contra doenças","Reabilitar o paciente após a doença","Fazer rastreamento"],"explicacao":"Protege o paciente do excesso de medicalização."},{"id":6802,"materia":"sus","nivel":2,"enunciado":"O rastreamento do câncer de mama com mamografia é prevenção:","opcoes":["Secundária","Primária","Terciária","Quaternária"],"explicacao":"Detecta a doença no início. A vacinação é primária."},{"id":6803,"materia":"sus","nivel":3,"enunciado":"Pela Lei 8.080/1990, a participação da iniciativa privada no SUS é complementar e dá preferência a:","opcoes":["Entidades filantrópicas e sem fins lucrativos","Empresas estrangeiras de saúde","Planos de saúde com fins lucrativos","Hospitais militares"],"explicacao":"Art. 199, § 1º, da Constituição e art. 25 da Lei 8.080/1990."},{"id":6804,"materia":"sus","nivel":0,"enunciado":"O telefone do SAMU é:","opcoes":["192","190","193","180"],"explicacao":"190 é a PM; 193, os Bombeiros."},{"id":6805,"materia":"med","nivel":3,"enunciado":"A tríade de Beck (hipotensão, turgência jugular e abafamento de bulhas) sugere:","opcoes":["Tamponamento cardíaco","Pneumotórax hipertensivo","Infarto inferior","Embolia pulmonar"],"explicacao":"Trata-se com pericardiocentese."},{"id":6806,"materia":"med","nivel":2,"enunciado":"O sinal de Blumberg positivo indica:","opcoes":["Irritação peritoneal","Colecistite crônica","Hérnia inguinal","Cálculo renal"],"explicacao":"Dor à descompressão brusca, como na apendicite."},{"id":6807,"materia":"med","nivel":3,"enunciado":"No choque séptico, a meta inicial de pressão arterial média é:","opcoes":["≥ 65 mmHg","≥ 100 mmHg","≥ 40 mmHg","≥ 120 mmHg"],"explicacao":"Com vasopressor, se o volume não bastar."},{"id":6808,"materia":"med","nivel":4,"enunciado":"Na sepse com hipotensão ou lactato elevado, a reposição inicial de cristaloide é de:","opcoes":["30 mL/kg nas primeiras 3 horas","5 mL/kg distribuídos em 24 horas","100 mL/kg na primeira hora","500 mL fixos"],"explicacao":"Recomendação da Surviving Sepsis Campaign."},{"id":6809,"materia":"med","nivel":4,"enunciado":"No infarto com supra de ST, o tempo ideal porta-balão para angioplastia é de até:","opcoes":["90 minutos","6 horas","12 horas","24 horas"],"explicacao":"Para trombólise, o ideal é porta-agulha de até 30 minutos."},{"id":6810,"materia":"med","nivel":2,"enunciado":"O antídoto da intoxicação por opioides é:","opcoes":["Naloxona","Flumazenil","Atropina","Vitamina K"],"explicacao":"Reverte a depressão respiratória."},{"id":6811,"materia":"med","nivel":2,"enunciado":"O antídoto dos benzodiazepínicos é:","opcoes":["Flumazenil","Naloxona","N-acetilcisteína","Protamina"],"explicacao":"Usado com cautela pelo risco de convulsões."},{"id":6812,"materia":"med","nivel":3,"enunciado":"Na intoxicação por paracetamol, o antídoto é:","opcoes":["N-acetilcisteína","Naloxona","Flumazenil","Azul de metileno"],"explicacao":"Protege o fígado."},{"id":6813,"materia":"med","nivel":3,"enunciado":"Na intoxicação por organofosforados (\"chumbinho\"), usa-se:","opcoes":["Atropina","Naloxona","Flumazenil","Glicose hipertônica"],"explicacao":"Combate os efeitos muscarínicos; pode-se associar pralidoxima."},{"id":6814,"materia":"med","nivel":3,"enunciado":"A cetoacidose diabética é marcada pela tríade:","opcoes":["Hiperglicemia, acidose metabólica e cetonemia","Hipoglicemia, alcalose respiratória e febre","Hipertensão, edema e proteinúria","Bradicardia, hipotermia e miose"],"explicacao":"Comum no diabetes tipo 1."},{"id":6815,"materia":"med","nivel":4,"enunciado":"Na cetoacidose diabética, só se inicia a insulina quando o potássio sérico estiver em, pelo menos:","opcoes":["3,3 mEq/L","2,0 mEq/L","5,5 mEq/L","6,0 mEq/L"],"explicacao":"A insulina joga o potássio para dentro das células e pode causar arritmias."},{"id":6816,"materia":"med","nivel":2,"enunciado":"Uma glicemia de jejum de 126 mg/dL ou mais, confirmada, indica:","opcoes":["Diabetes","Hipoglicemia","Glicemia normal","Pré-diabetes"],"explicacao":"Entre 100 e 125 mg/dL, é glicemia de jejum alterada."},{"id":6817,"materia":"med","nivel":3,"enunciado":"Uma hemoglobina glicada de 6,5% ou mais indica:","opcoes":["Diabetes","Pré-diabetes","Anemia","Normalidade"],"explicacao":"Entre 5,7% e 6,4%, pré-diabetes."},{"id":6818,"materia":"med","nivel":3,"enunciado":"No AVC isquêmico, a trombólise venosa com alteplase pode ser feita em até:","opcoes":["4,5 horas do início dos sintomas","24 horas do início dos sintomas","12 horas da chegada ao hospital","1 semana"],"explicacao":"Respeitados os critérios de inclusão e exclusão."},{"id":6819,"materia":"med","nivel":3,"enunciado":"A escala NIHSS é usada para avaliar:","opcoes":["A gravidade do AVC","O risco de queda","A dor no pós-operatório","A função renal"],"explicacao":"Quanto maior o escore, maior o déficit."},{"id":6820,"materia":"med","nivel":4,"enunciado":"Na pré-eclâmpsia grave, o sulfato de magnésio é usado para prevenir convulsões. Na intoxicação por ele, o antídoto é:","opcoes":["Gluconato de cálcio","Naloxona","Bicarbonato de sódio","Atropina"],"explicacao":"Sinais de alerta: perda de reflexos patelares e depressão respiratória."},{"id":6821,"materia":"med","nivel":2,"enunciado":"Na suspeita de dengue, deve-se evitar:","opcoes":["Anti-inflamatórios e AAS","Hidratação oral","Repouso","Paracetamol em dose habitual"],"explicacao":"Aumentam o risco de sangramento."},{"id":6822,"materia":"med","nivel":3,"enunciado":"São sinais de alarme na dengue, entre outros:","opcoes":["Dor abdominal intensa e vômitos persistentes","Febre baixa e coriza","Dor de cabeça leve","Manchas que coçam sem outros sintomas"],"explicacao":"Também sangramento de mucosas, letargia e queda brusca de plaquetas com hemoconcentração."},{"id":6823,"materia":"fisio","nivel":3,"enunciado":"O teste de Lachman avalia o:","opcoes":["Ligamento cruzado anterior","Menisco medial","Ligamento colateral lateral","Tendão patelar"],"explicacao":"É o teste mais sensível para essa lesão."},{"id":6824,"materia":"fisio","nivel":3,"enunciado":"O teste da gaveta posterior avalia o:","opcoes":["Ligamento cruzado posterior","Ligamento cruzado anterior","Menisco lateral","Tendão de Aquiles"],"explicacao":"Desloca-se a tíbia para trás com o joelho fletido."},{"id":6825,"materia":"fisio","nivel":2,"enunciado":"O teste de Phalen é usado na suspeita de:","opcoes":["Síndrome do túnel do carpo","Epicondilite lateral","Hérnia de disco lombar","Lesão do manguito rotador"],"explicacao":"Flexão máxima dos punhos reproduz parestesias."},{"id":6826,"materia":"fisio","nivel":3,"enunciado":"O teste de Finkelstein é usado na suspeita de:","opcoes":["Tenossinovite de De Quervain","Síndrome do túnel do carpo","Dedo em gatilho","Artrose do quadril"],"explicacao":"Dor no lado radial do punho com desvio ulnar."},{"id":6827,"materia":"fisio","nivel":3,"enunciado":"A manobra de Lasègue positiva sugere:","opcoes":["Compressão de raiz nervosa lombar","Lesão do menisco medial do joelho","Tendinite patelar crônica","Entorse de tornozelo"],"explicacao":"Dor irradiada ao elevar a perna estendida."},{"id":6828,"materia":"fisio","nivel":3,"enunciado":"Na escala de força do MRC, o grau 3 significa que o músculo:","opcoes":["Vence a gravidade, mas não a resistência","Não apresenta nenhuma contração visível","Vence resistência máxima do examinador","Só se move sem gravidade"],"explicacao":"Grau 4 vence alguma resistência; grau 5 é força normal."},{"id":6829,"materia":"fisio","nivel":4,"enunciado":"Na escala de força do MRC, o grau 2 corresponde a:","opcoes":["Movimento completo com a gravidade eliminada","Contração visível, sem nenhum movimento","Movimento completo contra a gravidade","Força normal"],"explicacao":"O grau 1 é só um esboço de contração."},{"id":6830,"materia":"fisio","nivel":4,"enunciado":"O escore total do MRC menor que 48 em paciente de UTI indica:","opcoes":["Fraqueza muscular adquirida na UTI","Força muscular normal para a idade","Paralisia completa dos quatro membros","Alta imediata"],"explicacao":"O escore vai de 0 a 60."},{"id":6831,"materia":"fisio","nivel":4,"enunciado":"Na ventilação protetora da síndrome do desconforto respiratório agudo, recomenda-se volume corrente de:","opcoes":["4 a 6 mL/kg de peso predito","10 a 12 mL/kg de peso real","15 mL/kg","1 a 2 mL/kg"],"explicacao":"Com pressão de platô até 30 cmH₂O."},{"id":6832,"materia":"fisio","nivel":2,"enunciado":"O incentivador respiratório é usado principalmente para:","opcoes":["Expandir os pulmões e prevenir atelectasias","Fortalecer os músculos das pernas","Reduzir a pressão arterial sistêmica","Tratar fraturas"],"explicacao":"Muito usado no pós-operatório."},{"id":6833,"materia":"fisio","nivel":3,"enunciado":"A marcha em tesoura é típica de:","opcoes":["Paralisia cerebral espástica","Doença de Parkinson","Lesão do nervo fibular","Hérnia de disco cervical"],"explicacao":"As pernas se cruzam pela espasticidade dos adutores."},{"id":6834,"materia":"fisio","nivel":2,"enunciado":"Após um AVC, a marcha em que o paciente arrasta a perna em semicírculo é chamada de:","opcoes":["Ceifante","Escarvante","Anserina","Festinante"],"explicacao":"A festinante é típica do Parkinson."},{"id":6835,"materia":"enf","nivel":3,"enunciado":"A escala de Morse é usada para avaliar o risco de:","opcoes":["Queda","Lesão por pressão","Delirium","Broncoaspiração"],"explicacao":"Considera histórico de quedas, diagnóstico secundário, auxílio na marcha, terapia venosa, marcha e estado mental."},{"id":6836,"materia":"fisio","nivel":3,"enunciado":"O teste de Thomas avalia:","opcoes":["Encurtamento dos flexores do quadril","Lesão do menisco medial","Instabilidade do ombro","Compressão do nervo mediano"],"explicacao":"A coxa oposta se eleva da maca quando há encurtamento."},{"id":6837,"materia":"med","nivel":4,"enunciado":"Pelos critérios de Light, o derrame pleural é exsudato quando a relação entre proteína pleural e sérica é maior que:","opcoes":["0,5","0,1","0,9","2"],"explicacao":"Também se a relação de LDH for maior que 0,6, entre outros critérios."},{"id":6838,"materia":"sus","nivel":2,"enunciado":"Pela Lei 8.080/1990, no município a direção do SUS cabe à:","opcoes":["Secretaria Municipal de Saúde ou órgão equivalente","Câmara de Vereadores","Prefeitura de outro município","Santa Casa local"],"explicacao":"Art. 9º, III, da Lei 8.080/1990."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('sus','enf','fisio','med') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
